using StackExchange.Redis;

public class NotificationService : BackgroundService
{
    private readonly IConnectionMultiplexer _redis;

    public NotificationService(IConnectionMultiplexer redis)
    {
        _redis = redis;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var sub = _redis.GetSubscriber();

        await sub.SubscribeAsync("notifications", (channel, message) =>
        {
            Console.WriteLine($"Received: {message}");
        });

        // Keep the service running
        await Task.Delay(Timeout.Infinite, stoppingToken);
    }

    public async Task PublishAsync(string message)
    {
        var sub = _redis.GetSubscriber();
        await sub.PublishAsync("notifications", message);
    }
}

const Redis = require('ioredis');
const sub = new Redis();
const pub = new Redis();

sub.subscribe('notifications', (err, count) => {
  if (err) console.error('Failed to subscribe:', err);
});

sub.on('message', (channel, message) => {
  console.log(`Received on ${channel}: ${message}`);
});

// Publish a message
async function sendNotification(message) {
  await pub.publish('notifications', message);
}

sendNotification('New order received!');
